488  Array_decodeBinary(void *UA_RESTRICT *UA_RESTRICT dst, size_t *out_length,
   489                     const UA_DataType *type, Ctx *ctx) {
   490      /* Decode the length */
   491      i32 signed_length;
   492      status ret = DECODE_DIRECT(&signed_length, UInt32); /* Int32 */
   493      if(ret != UA_STATUSCODE_GOOD)
   494          return ret;
   495
   496      /* Return early for empty arrays */
   497      if(signed_length <= 0) {
   498          *out_length = 0;
   499          if(signed_length < 0)
   500              *dst = NULL;
   501          else
   502              *dst = UA_EMPTY_ARRAY_SENTINEL;
   503          return UA_STATUSCODE_GOOD;
   504      }
   505
   506      /* Filter out arrays that can obviously not be decoded, because the message
   507       * is too small for the array length. This prevents the allocation of very
   508       * long arrays for bogus messages.*/
   509      size_t length = (size_t)signed_length;
   510      if(ctx->pos + ((type->memSize * length) / 32) > ctx->end)
   511          return UA_STATUSCODE_BADDECODINGERROR;
   512
   513      /* Allocate memory */
   514      *dst = UA_calloc(length, type->memSize);
   515      if(!*dst)
   516          return UA_STATUSCODE_BADOUTOFMEMORY;
   517
   518      if(type->overlayable) {
   519          /* memcpy overlayable array */
   520          if(ctx->end < ctx->pos + (type->memSize * length)) {
   521              UA_free(*dst);
   522              *dst = NULL;
   523              return UA_STATUSCODE_BADDECODINGERROR;
   524          }
   525          memcpy(*dst, ctx->pos, type->memSize * length);
   526          ctx->pos += type->memSize * length;
   527      } else {
   528          /* Decode array members */
   529          uintptr_t ptr = (uintptr_t)*dst;
   530          size_t decode_index = type->builtin ? type->typeIndex : UA_BUILTIN_TYPES_COUNT;
   531          for(size_t i = 0; i < length; ++i) {
   532              ret = decodeBinaryJumpTable[decode_index]((void*)ptr, type, ctx);
   533              if(ret != UA_STATUSCODE_GOOD) {
   534                  /* +1 because last element is also already initialized */
   535                  UA_Array_delete(*dst, i+1, type);
   536                  *dst = NULL;
   537                  return ret;
   538              }
   539              ptr += type->memSize;
   540          }
   541      }
   542      *out_length = length;
   543      return UA_STATUSCODE_GOOD;
   544  }
