   650  DECODE_BINARY(NodeId) {
   651      u8 dstByte = 0, encodingByte = 0;
   652      u16 dstUInt16 = 0;
   653
   654      /* Decode the encoding bitfield */
   655      status ret = DECODE_DIRECT(&encodingByte, Byte);
   656      if(ret != UA_STATUSCODE_GOOD)
   657          return ret;
   658
   659      /* Filter out the bits used only for ExpandedNodeIds */
   660      encodingByte &= (u8)~(UA_EXPANDEDNODEID_SERVERINDEX_FLAG |
   661                            UA_EXPANDEDNODEID_NAMESPACEURI_FLAG);
   662
   663      /* Decode the namespace and identifier */
   664      switch(encodingByte) {
   665      case UA_NODEIDTYPE_NUMERIC_TWOBYTE:
   666          dst->identifierType = UA_NODEIDTYPE_NUMERIC;
   667          ret = DECODE_DIRECT(&dstByte, Byte);
   668          dst->identifier.numeric = dstByte;
   669          dst->namespaceIndex = 0;
   670          break;
   671      case UA_NODEIDTYPE_NUMERIC_FOURBYTE:
   672          dst->identifierType = UA_NODEIDTYPE_NUMERIC;
   673          ret |= DECODE_DIRECT(&dstByte, Byte);
   674          dst->namespaceIndex = dstByte;
   675          ret |= DECODE_DIRECT(&dstUInt16, UInt16);
   676          dst->identifier.numeric = dstUInt16;
   677          break;
   678      case UA_NODEIDTYPE_NUMERIC_COMPLETE:
   679          dst->identifierType = UA_NODEIDTYPE_NUMERIC;
   680          ret |= DECODE_DIRECT(&dst->namespaceIndex, UInt16);
   681          ret |= DECODE_DIRECT(&dst->identifier.numeric, UInt32);
   682          break;
   683      case UA_NODEIDTYPE_STRING:
   684          dst->identifierType = UA_NODEIDTYPE_STRING;
   685          ret |= DECODE_DIRECT(&dst->namespaceIndex, UInt16);
   686          ret |= DECODE_DIRECT(&dst->identifier.string, String);
   687          break;
   688      case UA_NODEIDTYPE_GUID:
   689          dst->identifierType = UA_NODEIDTYPE_GUID;
   690          ret |= DECODE_DIRECT(&dst->namespaceIndex, UInt16);
   691          ret |= DECODE_DIRECT(&dst->identifier.guid, Guid);
   692          break;
   693      case UA_NODEIDTYPE_BYTESTRING:
   694          dst->identifierType = UA_NODEIDTYPE_BYTESTRING;
   695          ret |= DECODE_DIRECT(&dst->namespaceIndex, UInt16);
   696          ret |= DECODE_DIRECT(&dst->identifier.byteString, String); /* ByteString */
   697          break;
   698      default:
   699          ret |= UA_STATUSCODE_BADINTERNALERROR;
   700          break;
   701      }
   702      return ret;
   703  }
