   705  /* ExpandedNodeId */
   850              break;
   851          default:
   852              ret = UA_STATUSCODE_BADINTERNALERROR;
   853          }
   854          return ret;
   855      }
   856
   857      /* Cannot encode with no data or no type description */
   858      if(!src->content.decoded.type || !src->content.decoded.data)
   859          return UA_STATUSCODE_BADENCODINGERROR;
   860
   861      /* Write the NodeId for the binary encoded type. The NodeId is always
   862       * numeric, so no buffer replacement is taking place. */
   863      UA_NodeId typeId = src->content.decoded.type->typeId;
   864      if(typeId.identifierType != UA_NODEIDTYPE_NUMERIC)
   865          return UA_STATUSCODE_BADENCODINGERROR;
   866      typeId.identifier.numeric = src->content.decoded.type->binaryEncodingId;
   867      status ret = ENCODE_DIRECT(&typeId, NodeId);
   868
   869      /* Write the encoding byte */
   870      encoding = UA_EXTENSIONOBJECT_ENCODED_BYTESTRING;
   871      ret |= ENCODE_DIRECT(&encoding, Byte);
   872
   873      /* Compute the content length */
   874      const UA_DataType *contentType = src->content.decoded.type;
   875      size_t len = UA_calcSizeBinary(src->content.decoded.data, contentType);
   876
   877      /* Encode the content length */
   878      if(len > UA_INT32_MAX)
   879          return UA_STATUSCODE_BADENCODINGERROR;
   880      i32 signed_len = (i32)len;
   881      ret |= ENCODE_DIRECT(&signed_len, UInt32); /* Int32 */
   882
   883      /* Return early upon failures (no buffer exchange until here) */
   884      if(ret != UA_STATUSCODE_GOOD)
   885          return ret;
   886
   887      /* Encode the content */
   888      return encodeBinaryInternal(src->content.decoded.data, contentType, ctx);
   889  }
